// Turns whatever the fetch step returned into a common story format.
// Always returns at least one item, so the main workflow never gets nothing back.
const src = $('When called').first().json;

const toTime = (value) => {
  const t = Date.parse(value);
  return Number.isNaN(t) ? null : t;
};

const errorText = (e) =>
  typeof e === 'string' ? e : (e && (e.message || e.description)) || JSON.stringify(e);

const stories = [];
let error = null;

for (const { json: j } of $input.all()) {
  if (!j || Object.keys(j).length === 0) continue; // empty item from "Always Output Data"
  if (j.error) {
    error = errorText(j.error);
    continue;
  }

  if (Array.isArray(j.hits)) {
    // Hacker News (Algolia API)
    for (const h of j.hits) {
      stories.push({
        title: h.title,
        url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
        published: h.created_at_i ? h.created_at_i * 1000 : toTime(h.created_at),
        points: h.points ?? 0,
      });
    }
  } else if (j.short_id && j.title) {
    // Lobsters (one item per story)
    stories.push({
      title: j.title,
      url: j.url || j.comments_url,
      published: toTime(j.created_at),
      points: j.score ?? 0,
    });
  } else if (j.title && j.link) {
    // RSS / Atom item
    stories.push({
      title: j.title,
      url: j.link,
      published: toTime(j.isoDate || j.pubDate),
      points: null, // RSS has no popularity data
    });
  }
}

const valid = stories.filter(s => s.title && s.url);

if (valid.length === 0) {
  return [{ json: { source: src.name, failed: true, error: error || 'No stories returned' } }];
}

return valid.map(s => ({ json: { source: src.name, ...s } }));
